sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	var roi = api.data.record?.form?.fields?.year_one_net_roi?.value;
    roi = parseFloat(roi.split(';')[1]) || 0;

    // Scaling factor controls how quickly ROI moves
    // away from the center.
    // 100000 means:
    // $100K gives a noticeable movement,
    // larger values gradually approach 100.
    var roiScale = 100000;

    var roiX;

    // Positive ROI → 50 to 100
    // Negative ROI → 50 to 0
    roiX = 50 + (Math.atan(roi / roiScale) / (Math.PI / 2)) * 50;

    return roiX;
}
